// Package murmur3 implements the MurmurHash3 hash algorithm.
//
// Package implements Austin Appleby's MurmurHash3 algorithm.
//
// MurmurHash3 is a fast, non-cryptographic hash function well suited for hash
// tables, bloom filters, data partitioning, and deduplication where speed and
// good distribution matter more than cryptographic security.
//
// References:
//
//	https://en.wikipedia.org/wiki/MurmurHash#Algorithm
//	https://github.com/aappleby/smhasher/blob/master/src/MurmurHash3.cpp
package murmur3

import "strconv"

// EncodeToString returns the hexadecimal encoding of a hash value.
func EncodeToString(sum uint64) string {
	return strconv.FormatUint(sum, 16)
}

package murmur3

import (
	"hash"
	"math/bits"
)

const (
	c1          = 0xcc9e2d51
	c2          = 0x1b873593
	r1          = 15
	r2          = 13
	blockSize32 = 4
	hashSize32  = 4
)

type digest32 struct {
	seed           uint32
	h1             uint32
	tail           [4]byte
	tailBytesCount int
	writtenLen     int
}

// New32 returns a new hash.Hash32 computing the MurmurHash3 hash.
// It can generate 2 to the power of 32 unique 32-bit values ranging
// from 0 to 4_294_967_296.
// Hash is not collision safe, so it's recommended to handle potential
// collisions when dealing with more than 65_536 values which is when
// probability raises.
func New32() hash.Hash32 {
	return &digest32{}
}

// NewWithSeed32 returns a new hash.Hash32 computing the MurmurHash3
// hash with the given seed.
// It can generate 2 to the power of 32 unique 32-bit values ranging
// from 0 to 4_294_967_296.
// Hash is not collision safe, so it's recommended to handle potential
// collisions when dealing with more than 65_536 values which is when
// provability raises.
func NewWithSeed32(seed uint32) hash.Hash32 {
	return &digest32{seed: seed, h1: seed}
}

// Sum32 returns the MurmurHash3 hash of the specified data.
func Sum32(data []byte) uint32 {
	return Sum32WithSeed(data, 0)
}

// Sum32WithSeed returns the MurmurHash3 hash of the specified data
// using the given seed.
func Sum32WithSeed(data []byte, seed uint32) uint32 {
	h := NewWithSeed32(seed)
	h.Write(data)
	return h.Sum32()
}

func (digest32) BlockSize() int {
	return blockSize32
}

func (digest32) Size() int {
	return hashSize32
}

func (d *digest32) Reset() {
	d.h1 = d.seed
	d.tailBytesCount = 0
	d.writtenLen = 0
}

func (d *digest32) Write(bz []byte) (int, error) {
	// Keep track of all written bytes
	total := len(bz)
	d.writtenLen += total

	// If there are leftover bytes in the tail,
	// try to fill a block with the new data.
	if d.tailBytesCount > 0 {
		need := blockSize32 - d.tailBytesCount
		if len(bz) < need {
			// Append more data to the block
			copy(d.tail[d.tailBytesCount:], bz)
			d.tailBytesCount += len(bz)

			// Tail block is still not filled
			return total, nil
		}

		// Append remaining block data and process current block
		copy(d.tail[d.tailBytesCount:], bz[:need])
		d.processBlock(d.tail[:])

		// Update data to exclude the appended processed data
		bz = bz[need:]
		d.tailBytesCount = 0
	}

	// Process full 4-byte blocks
	for len(bz) >= blockSize32 {
		d.processBlock(bz[:blockSize32])
		bz = bz[blockSize32:]
	}

	// Save remaining bytes in the tail. Remaining data can be left
	// out of the last block when data size is less than 4 bytes.
	if len(bz) > 0 {
		d.tailBytesCount = copy(d.tail[:], bz)
	}

	return total, nil
}

func (d digest32) Sum32() uint32 {
	h1 := d.h1

	// Process tail bytes when they exist. Blocks have 4 bytes, so depending
	// on the size of the data some bytes might not be processed after the last
	// write if the last block has less than 4 bytes.
	var k1 uint32
	switch d.tailBytesCount {
	case 3:
		k1 ^= uint32(d.tail[2]) << 16
		fallthrough
	case 2:
		k1 ^= uint32(d.tail[1]) << 8
		fallthrough
	case 1:
		k1 ^= uint32(d.tail[0])
		k1 *= c1
		k1 = bits.RotateLeft32(k1, r1)
		k1 *= c2
		h1 ^= k1
	}

	// Finalization mix
	h1 ^= uint32(d.writtenLen)

	h1 ^= h1 >> 16
	h1 *= 0x85ebca6b
	h1 ^= h1 >> r2
	h1 *= 0xc2b2ae35
	h1 ^= h1 >> 16

	return h1
}

func (d digest32) Sum(bz []byte) []byte {
	// Append hash in little-endian order
	s := d.Sum32()
	return append(bz, byte(s), byte(s>>8), byte(s>>16), byte(s>>24))
}

// processBlock reads a 4-byte little-endian block
// and mixes it into the hash state.
func (d *digest32) processBlock(bz []byte) {
	k1 := uint32(bz[0]) | uint32(bz[1])<<8 | uint32(bz[2])<<16 | uint32(bz[3])<<24
	k1 *= c1
	k1 = bits.RotateLeft32(k1, r1)
	k1 *= c2

	d.h1 ^= k1
	d.h1 = bits.RotateLeft32(d.h1, r2)
	d.h1 = d.h1*5 + 0xe6546b64 // MurmurHash3 "m" = 5, "n" = 0xe6546b64
}

package murmur3

import "hash"

const hashSize64 = 8

type digest64 struct {
	d1 digest32
	d2 digest32
}

// New64 returns a new hash.Hash64 computing a 64-bit MurmurHash3
// hash using two 32-bit hashes with different seeds.
// It can generate 2 to the power of 64 unique 64-bit values.
// Hash is not collision safe, so it's recommended to handle potential
// collisions when dealing with more than 4_294_967_296 values which is
// when probability raises.
func New64() hash.Hash64 {
	return &digest64{
		d1: digest32{},
		d2: digest32{seed: 1, h1: 1},
	}
}

// NewWithSeed64 returns a new hash.Hash64 computing a 64-bit
// MurmurHash3 hash. The first 32-bit hash uses seed1 and the
// second uses seed2. The two seeds should ideally be different.
// It can generate 2 to the power of 64 unique 64-bit values.
// Hash is not collision safe, so it's recommended to handle potential
// collisions when dealing with more than 4_294_967_296 values which is
// when provability raises.
func NewWithSeed64(seed1, seed2 uint32) hash.Hash64 {
	return &digest64{
		d1: digest32{seed: seed1, h1: seed1},
		d2: digest32{seed: seed2, h1: seed2},
	}
}

// Sum64 returns the 64-bit MurmurHash3 hash of the specified data.
func Sum64(data []byte) uint64 {
	return Sum64WithSeed(data, 0, 1)
}

// Sum64WithSeed returns the 64-bit MurmurHash3 hash of the specified
// data using the given seeds.
func Sum64WithSeed(data []byte, seed1, seed2 uint32) uint64 {
	h := NewWithSeed64(seed1, seed2)
	h.Write(data)
	return h.Sum64()
}

func (digest64) BlockSize() int {
	// Use a 32-bit hash block size because writes are
	// done to two hash32 hashes using the same data.
	return blockSize32
}

func (digest64) Size() int {
	return hashSize64
}

func (d *digest64) Reset() {
	d.d1.Reset()
	d.d2.Reset()
}

func (d *digest64) Write(bz []byte) (int, error) {
	d.d1.Write(bz)
	return d.d2.Write(bz)
}

func (d digest64) Sum64() uint64 {
	return uint64(d.d1.Sum32())<<32 | uint64(d.d2.Sum32())
}

func (d digest64) Sum(bz []byte) []byte {
	s := d.Sum64()
	return append(bz,
		byte(s), byte(s>>8), byte(s>>16), byte(s>>24),
		byte(s>>32), byte(s>>40), byte(s>>48), byte(s>>56),
	)
}

package bitset

import "strings"

const bitsPerWord = 64

// BitSet implements an arbitrary-size bit array.
type BitSet struct {
	words []uint64
}

// New creates a new BitSet pre-allocated to hold at least size bits.
func New(size uint64) BitSet {
	if size == 0 {
		return BitSet{}
	}
	return BitSet{words: make([]uint64, wordIndex(size-1)+1)}
}

// Set turns on the bit at a given position.
func (b *BitSet) Set(i uint64) {
	idx := wordIndex(i)
	if idx >= len(b.words) {
		b.grow(idx + 1)
	}
	b.words[idx] |= bitMask(i) // Turn bit on
}

// Clear turns off the bit at a given position.
func (b *BitSet) Clear(i uint64) {
	idx := wordIndex(i)
	if idx < len(b.words) {
		b.words[idx] &^= bitMask(i) // Turn bit off
	}
}

// ClearAll turns off all bits.
// The size of the bitset remains unchanged.
func (b *BitSet) ClearAll() {
	for i := range b.words {
		b.words[i] = 0
	}
}

// Compact reclaims memory by removing trailing zero words.
func (b *BitSet) Compact() {
	end := len(b.words)
	for ; end > 0 && b.words[end-1] == 0; end-- {
	}
	words := make([]uint64, end)
	copy(words, b.words)
	b.words = words
}

// IsSet checks whether the bit at a given position is set.
func (b BitSet) IsSet(i uint64) bool {
	idx := wordIndex(i)
	if idx >= len(b.words) {
		return false // Bit has not been set yet
	}
	return b.words[idx]&bitMask(i) != 0
}

// Size returns the total number of bits (including unset) currently stored.
// It's the total space allocated within the set in bits.
func (b BitSet) Size() int {
	return len(b.words) * bitsPerWord
}

// Len returns the number of set bits.
func (b BitSet) Len() int {
	var count int
	for _, w := range b.words {
		count += countSetBits(w)
	}
	return count
}

// And performs an in-place AND with other bitset.
// Bits beyond the other bitset are cleared.
func (b *BitSet) And(other BitSet) {
	for i := range b.words {
		if i < len(other.words) {
			b.words[i] &= other.words[i]
		} else {
			b.words[i] = 0
		}
	}
}

// Or performs an in-place OR (union) with other bitset.
// Current bitset grows if the other bitset is bigger.
func (b *BitSet) Or(other BitSet) {
	otherLen := len(other.words)
	if otherLen > len(b.words) {
		b.grow(otherLen)
	}

	for i := range other.words {
		b.words[i] |= other.words[i]
	}
}

// Xor performs an in-place XOR with other.
// Current bitset grows if the other bitset is bigger.
func (b *BitSet) Xor(other BitSet) {
	otherLen := len(other.words)
	if otherLen > len(b.words) {
		b.grow(otherLen)
	}

	for i := range other.words {
		b.words[i] ^= other.words[i]
	}
}

// Equal checks whether other bitset have exactly the same bits set.
func (b BitSet) Equal(other BitSet) bool {
	short, long := b.words, other.words
	if len(short) > len(long) {
		short, long = long, short
	}

	for i := range short {
		if short[i] != long[i] {
			return false
		}
	}

	// Any trailing words in the longer set must be zero
	for i := len(short); i < len(long); i++ {
		if long[i] != 0 {
			return false
		}
	}
	return true
}

// PaddedString returns a binary representation of the bitset with zero padding.
// Representation uses MSB-first binary representation.
func (b BitSet) PaddedString() string {
	wordCount := len(b.words)
	if wordCount == 0 {
		return ""
	}

	buf := make([]byte, wordCount*bitsPerWord)
	for i, w := range b.words {
		base := (wordCount - 1 - i) * bitsPerWord
		for j := 0; j < bitsPerWord; j++ {
			if w>>uint64(bitsPerWord-1-j)&1 == 1 {
				buf[base+j] = '1'
			} else {
				buf[base+j] = '0'
			}
		}
	}
	return string(buf)
}

// String returns a binary representation of the bitset.
// Representation uses MSB-first binary representation.
func (b BitSet) String() string {
	s := strings.TrimLeft(b.PaddedString(), "0")
	if s == "" && len(b.words) > 0 {
		return "0"
	}
	return s
}

func (b *BitSet) grow(length int) {
	words := make([]uint64, length)
	copy(words, b.words)
	b.words = words
}

func wordIndex(i uint64) int {
	return int(i / bitsPerWord)
}

func bitMask(i uint64) uint64 {
	return 1 << (i % bitsPerWord)
}

func countSetBits(x uint64) int {
	// Count the number of set bits using Kernighan's algorithm
	var count int
	for x != 0 {
		x &= x - 1
		count++
	}
	return count
}

// Package bloom implements a Bloom filter, a space-efficient probabilistic
// data structure used to test whether an element is a member of a set.
//
// A Bloom filter never reports a false negative; If Contains returns false,
// the element was definitely never added. It may report a false positive.
//
// Contains can return true for an element that was never added. The chance of
// a false positive grows as more elements are added and can be traded against
// memory usage when the filter is created.
package bloom

import (
	"math"

	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/bitset"
	"gno.land/p/g17khqpukees4237dtn3astzapmp462vjhsz6st4/murmur3"
)

// Bloom is a probabilistic set-membership filter.
type Bloom struct {
	bits bitset.BitSet
	m    uint64 // Number of bits in the filter
	k    uint64 // Number of hash positions set per element
}

// NewWithMK creates a filter with an explicit bit-array size m and hash count k.
// It is the low-level constructor for callers who already know the parameters;
// Most users should prefer New. Both m and k are clamped to a minimum of 1.
func NewWithMK(m, k uint64) *Bloom {
	if m < 1 {
		m = 1
	}

	if k < 1 {
		k = 1
	}

	return &Bloom{
		bits: bitset.New(m),
		m:    m,
		k:    k,
	}
}

// New creates a filter sized to hold up to maxItems elements while keeping the
// false-positive probability around falsePositiveRate (for example 0.01 for 1%).
// It computes the optimal number of bits and hash functions and delegates to
// NewWithMK. Invalid inputs (maxItems == 0, or a rate outside the open interval
// (0, 1)) fall back to a minimal usable filter.
func New(maxItems uint64, falsePositiveRate float64) *Bloom {
	if maxItems == 0 || falsePositiveRate <= 0 || falsePositiveRate >= 1 {
		return NewWithMK(1, 1)
	}

	n := float64(maxItems)
	ln2 := math.Ln2

	// m = ceil( -(n * ln(p)) / (ln2)^2 )
	m := uint64(math.Ceil(-(n * math.Log(falsePositiveRate)) / (ln2 * ln2)))

	// k = round( (m/n) * ln2 )
	k := uint64(math.Round((float64(m) / n) * ln2))

	return NewWithMK(m, k)
}

// Capacity returns the capacity "m" of the filter.
func (b *Bloom) Capacity() uint64 {
	return b.m
}

// HashFunctions returns the number of hash functions "k" of the filter.
func (b *Bloom) HashFunctions() uint64 {
	return b.k
}

// Reset clears all values from the filter, keeping its capacity and hash count.
func (b *Bloom) Reset() *Bloom {
	b.bits.ClearAll()
	return b
}

// Add inserts data into the filter.
func (b *Bloom) Add(data []byte) *Bloom {
	h1, h2 := hashes(data)
	for i := uint64(0); i < b.k; i++ {
		b.bits.Set(b.index(h1, h2, i))
	}
	return b
}

// AddString inserts string data into the filter.
func (b *Bloom) AddString(data string) *Bloom {
	return b.Add([]byte(data))
}

// Contains checks whether data is possibly in the set.
// A false result means data was definitely never added.
// A true result means data was probably added but may be a false positive.
func (b *Bloom) Contains(data []byte) bool {
	h1, h2 := hashes(data)
	for i := uint64(0); i < b.k; i++ {
		if !b.bits.IsSet(b.index(h1, h2, i)) {
			return false
		}
	}
	return true
}

// ContainsString checks whether string data is possibly in the set.
// A false result means data was definitely never added.
// A true result means data was probably added but may be a false positive.
func (b *Bloom) ContainsString(data string) bool {
	return b.Contains([]byte(data))
}

// index returns the i-th bit position for an element using double hashing.
func (b *Bloom) index(h1, h2 uint32, i uint64) uint64 {
	return (uint64(h1) + i*uint64(h2)) % b.m
}

// hashes splits a single 64-bit MurmurHash3 hash of data into two 32-bit halves
// used as the seeds for double hashing.
func hashes(data []byte) (h1, h2 uint32) {
	sum := murmur3.Sum64(data)
	return uint32(sum >> 32), uint32(sum)
}

# Message Package

Package provides a simple message broker implementation.

The message broker is a Pub/Sub one. It implements two different interfaces,
`Publisher` and `Subscriber`, which are also defined within this package.

Published messages contain the topic where they are published and optional
message data. Subscribing to the `TopicAll` topic triggers the callback for
messages published to any topic.

Repository can be found at [jeronimoalbi/gnome](https://github.com/jeronimoalbi/gnome),
as part of `jeronimoalbi`'s Gno smart contracts monorepo.

## Usage

[embedmd]:# (filetests/readme_filetest.gno go)
```go
package main

import "gno.land/p/jeronimoalbi/message"

func main() {
	broker := message.NewBroker()

	// Subscribe to an event
	subID, err := broker.Subscribe("EventName", func(msg message.Message) {
		println("EventName has been triggered:", msg.Data.(string))
	})
	if err != nil {
		panic(err)
	}

	// Publish an event
	err = broker.Publish("EventName", "Example event data")
	if err != nil {
		panic(err)
	}

	// Unsubscribe from the event
	unsubscribed, err := broker.Unsubscribe("EventName", subID)
	if err != nil {
		panic(err)
	}

	if !unsubscribed {
		panic("subscription not found")
	}

	// Nothing is triggered after unsubscribing
	err = broker.Publish("EventName", "Ignored event data")
	if err != nil {
		panic(err)
	}
}

// Output:
// EventName has been triggered: Example event data
```

package message

import (
	"errors"
	"strings"

	"gno.land/p/moul/ulist/v0"
	"gno.land/p/nt/bptree/v0"
)

var (
	// ErrInvalidTopic is triggered when an invalid topic is used.
	ErrInvalidTopic = errors.New("invalid topic")

	// ErrRequiredCallback is triggered when subscribing without a callback.
	ErrRequiredCallback = errors.New("message callback is required")

	// ErrRequiredSubscriptionID is triggered when unsubscribing without an ID.
	ErrRequiredSubscriptionID = errors.New("message sibscription ID is required")

	// ErrRequiredTopic is triggered when (un)subscribing without a topic.
	ErrRequiredTopic = errors.New("message topic is required")
)

// NewBroker creates a new message broker.
func NewBroker() *Broker {
	return &Broker{
		callbacks: bptree.NewBPTree32(),
	}
}

// Broker is a message broker that handles subscriptions and message publishing.
type Broker struct {
	callbacks *bptree.BPTree // string(topic) -> *ulist.List(Callback)
}

// Topics returns the list of current subscription topics.
func (b *Broker) Topics() []Topic {
	var topics []Topic
	b.callbacks.Iterate("", "", func(k string, _ any) bool {
		topic := Topic(k)
		if topic == TopicAll {
			// Skip catchall topic from the list
			return false
		}

		topics = append(topics, topic)
		return false
	})
	return topics
}

// Subscribe subscribes to messages published for a topic.
// It returns the callback ID within the topic.
func (b *Broker) Subscribe(topic Topic, cb Callback) (id int, _ error) {
	key := strings.TrimSpace(string(topic))
	if key == "" {
		return 0, ErrRequiredTopic
	}

	if cb == nil {
		return 0, ErrRequiredCallback
	}

	callbacks, _ := b.callbacks.Get(key).(*ulist.List)
	if callbacks == nil {
		callbacks = ulist.New()
	}

	callbacks.Append(cb)
	b.callbacks.Set(key, callbacks)
	return callbacks.TotalSize(), nil
}

// Unsubscribe unsubscribes a callback from a message topic.
// ID is the callback ID within the topic, returned on subscription.
func (b *Broker) Unsubscribe(topic Topic, id int) (unsubscribed bool, _ error) {
	key := strings.TrimSpace(string(topic))
	if key == "" {
		return false, ErrRequiredTopic
	}

	if id == 0 {
		return false, ErrRequiredSubscriptionID
	}

	callbacks, ok := b.callbacks.Get(key).(*ulist.List)
	if !ok {
		return false, errors.New("message topic not found: " + key)
	}

	i := id - 1
	return callbacks.Delete(i) == nil, nil
}

// Publish publishes a message for a topic.
func (b *Broker) Publish(topic Topic, data any) error {
	if topic == TopicAll {
		return ErrInvalidTopic
	}

	key := strings.TrimSpace(string(topic))
	if key == "" {
		return ErrRequiredTopic
	}

	iterCb := func(_ int, v any) bool {
		cb := v.(Callback)
		cb(Message{topic, data})
		return false
	}

	// Trigger callbacks subscribed to current topic
	if callbacks, ok := b.callbacks.Get(key).(*ulist.List); ok {
		callbacks.Iterator(0, callbacks.Size(), iterCb)
	}

	// Trigger callbacks subscribed to all topics
	if callbacks, ok := b.callbacks.Get(string(TopicAll)).(*ulist.List); ok {
		callbacks.Iterator(0, callbacks.Size(), iterCb)
	}
	return nil
}

// Package message provides a simple message broker implementation.
package message

// TopicAll defines a topic for all types of message.
// This topic can be used to subscribe to message for all topics.
const TopicAll Topic = "*"

type (
	// Topic defines a type for message topics.
	Topic string

	// Callback defines a type for message callbacks.
	Callback func(Message)

	// Message defines a type for published messages.
	Message struct {
		// Topic is the message topic.
		Topic Topic

		// Data contains optional message data.
		Data any
	}

	// Publisher defines an interface for message publishers.
	Publisher interface {
		// Publish publishes a message for a topic.
		Publish(_ Topic, data any) error
	}

	// Subscriber defines an interface for message subscribers.
	Subscriber interface {
		// Subscribe subscribes to messages published for a topic.
		// It returns the callback ID within the topic.
		Subscribe(Topic, Callback) (id int, _ error)

		// Unsubscribe unsubscribes a callback from a message topic.
		// ID is the callback ID within the topic, returned on subscription.
		Unsubscribe(_ Topic, id int) (unsubscribed bool, _ error)
	}
)
